51	export const loader = async ({ request }: LoaderFunctionArgs) => {
52	  const { session } = await authenticate.admin(request);
53	  const shop = session.shop;
54	
55	  const [entries, subscription] = await Promise.all([
56	    db.waitlistEntry.findMany({
57	      where: { shop },
58	      orderBy: { createdAt: "desc" },
59	    }),
60	    getShopSubscription(shop),
61	  ]);
62	
63	  const stats = {
64	    total: entries.length,
65	    waiting: entries.filter((e) => e.status === "waiting").length,
66	    accepted: entries.filter((e) => e.status === "accepted").length,
67	    notified: entries.filter((e) => e.status === "notified").length,
68	    converted: entries.filter((e) => e.status === "converted").length,
69	    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
70	  };
71	
72	  return { entries, stats, subscription };
73	};
74	
75	export const action = async ({ request }: ActionFunctionArgs) => {
76	  const { session } = await authenticate.admin(request);
77	  const shop = session.shop;
78	  const formData = await request.formData();
79	  const intent = formData.get("intent");
80	
81	  // Fetch email sender settings once for any action that may send emails
82	  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
83	  const emailOpts: EmailOptions = {
84	    senderName: shopSettings?.emailSenderName,
85	    shopDisplayName: shopSettings?.shopName,
86	    replyTo: shopSettings?.emailReplyTo,
87	  };
88	
89	  if (intent === "add") {
90	    const email = String(formData.get("email") || "").trim().toLowerCase();
91	    const zipCode = String(formData.get("zipCode") || "")
92	      .trim()
93	      .toUpperCase();
94	    const note = String(formData.get("note") || "").trim() || null;
95	
96	    if (!email || !zipCode) return { error: "Email and zip code are required." };
97	
98	    const subscription = await getShopSubscription(shop);
99	    const limits = PLAN_LIMITS[subscription.planTier];
100	
101	    if (limits.maxWaitlist === 0) {
102	      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
103	    }
104	
105	    if (limits.maxWaitlist < UNLIMITED) {
106	      const currentCount = await db.waitlistEntry.count({ where: { shop } });
107	      if (currentCount >= limits.maxWaitlist) {
108	        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
109	      }
110	    }
111	
112	    try {
113	      await db.waitlistEntry.create({
114	        data: { shop, email, zipCode, note },
115	      });
116	      return { success: true, action: "added" };
117	    } catch {
118	      return { error: "This email is already on the waitlist for this zip code." };
119	    }
120	  }
121	
122	  if (intent === "delete") {
123	    const id = String(formData.get("id"));
124	    try {
125	      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
126	      if (!existing) return { error: "Entry not found." };
127	      await db.waitlistEntry.delete({ where: { id } });
128	      return { success: true, action: "deleted" };
129	    } catch {
130	      return { error: "Failed to delete entry." };
131	    }
132	  }
133	
134	  if (intent === "update-status") {
135	    const id = String(formData.get("id"));
136	    const status = String(formData.get("status"));
137	    try {
138	      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
139	      if (!existing) return { error: "Entry not found." };
140	      await db.waitlistEntry.update({ where: { id }, data: { status } });
141	      return { success: true, action: "updated" };
142	    } catch {
143	      return { error: "Failed to update entry status." };
144	    }
145	  }
146	
147	  if (intent === "notify-zip") {
148	    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
149	    if (!zipCode) return { error: "No ZIP code specified." };
150	
151	    const notifyZipSub = await getShopSubscription(shop);
152	    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
153	      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
154	    }
155	
156	    const notifyZipEntries = await db.waitlistEntry.findMany({
157	      where: { shop, zipCode, status: "waiting" },
158	      select: { id: true, email: true },
159	    });
160	
161	    if (notifyZipEntries.length === 0) {
162	      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
163	    }
164	
165	    await db.waitlistEntry.updateMany({
166	      where: { shop, zipCode, status: "waiting" },
167	      data: { status: "notified" },
168	    });
169	
170	    const emails = notifyZipEntries.map((e) => e.email);
171	    const shopUrl = `https://${shop}`;
172	    const emailResults = await Promise.allSettled(
173	      emails.map((email) =>
174	        sendZipAvailableNotification(email, zipCode, shop, shopUrl, emailOpts),
175	      ),
176	    );
177	    const emailsSent = emailResults.filter(
178	      (r) => r.status === "fulfilled" && r.value,
179	    ).length;
180	
181	    return { action: "notify-zip", zipCode, emails, count: emails.length, emailsSent };
182	  }
183	
184	  if (intent === "notify-selected-zips") {
185	    const zipCodesRaw = String(formData.get("zipCodes") || "");
186	    const zipCodes = zipCodesRaw.split(",").map(z => z.trim().toUpperCase()).filter(Boolean);
187	    if (zipCodes.length === 0) return { error: "No ZIP codes selected." };
188	
189	    const notifyZipsSub = await getShopSubscription(shop);
190	    if (PLAN_LIMITS[notifyZipsSub.planTier].maxWaitlist < UNLIMITED) {
191	      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
192	    }
193	
194	    const waitingEntries = await db.waitlistEntry.findMany({
195	      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
196	      select: { id: true, email: true, zipCode: true },
197	    });
198	
199	    if (waitingEntries.length === 0) {
200	      return { action: "notify-selected-zips", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
201	    }
202	
203	    await db.waitlistEntry.updateMany({
204	      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
205	      data: { status: "notified" },
206	    });
207	
208	    const zipMap = new Map<string, number>();
209	    for (const entry of waitingEntries) {
210	      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
211	    }
212	    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
213	    const emails = waitingEntries.map(e => e.email);
214	
215	    const shopUrl = `https://${shop}`;
216	    const emailResults = await Promise.allSettled(
217	      waitingEntries.map((e) =>
218	        sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl, emailOpts),
219	      ),
220	    );
221	    const emailsSent = emailResults.filter(
222	      (r) => r.status === "fulfilled" && r.value,
223	    ).length;
224	
225	    return { action: "notify-selected-zips", emails, count: emails.length, zipBreakdown, emailsSent };
226	  }
227	
228	  if (intent === "bulk-action") {
229	    const idsRaw = String(formData.get("ids") || "");
230	    const ids = idsRaw.split(",").filter(Boolean);
231	    const bulkType = String(formData.get("bulkType") || "");
232	
233	    if (ids.length === 0) return { error: "No entries selected." };
234	
235	    const bulkSub = await getShopSubscription(shop);
236	
237	    if (bulkType === "notify") {
238	      if (PLAN_LIMITS[bulkSub.planTier].maxWaitlist < UNLIMITED) {
239	        return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
240	      }
241	      const entriesToNotify = await db.waitlistEntry.findMany({
242	        where: { id: { in: ids }, shop, status: "waiting" },
243	        select: { id: true, email: true, zipCode: true },
244	      });
245	      if (entriesToNotify.length === 0) {
246	        return { action: "bulk-action-notify", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
247	      }
248	      await db.waitlistEntry.updateMany({
249	        where: { id: { in: ids }, shop, status: "waiting" },
250	        data: { status: "notified" },
251	      });
252	      const zipMap = new Map<string, number>();
253	      for (const e of entriesToNotify) {
254	        zipMap.set(e.zipCode, (zipMap.get(e.zipCode) ?? 0) + 1);
255	      }
256	      const zipBreakdown = Array.from(zipMap.entries()).map(([z, c]) => ({ zipCode: z, count: c }));
257	
258	      const shopUrl = `https://${shop}`;
259	      const emailResults = await Promise.allSettled(
260	        entriesToNotify.map((e) =>
261	          sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl, emailOpts),
262	        ),
263	      );
264	      const emailsSent = emailResults.filter(
265	        (r) => r.status === "fulfilled" && r.value,
266	      ).length;
267	
268	      return { action: "bulk-action-notify", emails: entriesToNotify.map(e => e.email), count: entriesToNotify.length, zipBreakdown, emailsSent };
269	    }
270	
271	    if (bulkType === "accept") {
272	      const entriesToAccept = await db.waitlistEntry.findMany({
273	        where: { id: { in: ids }, shop },
274	        select: { id: true, email: true, name: true, zipCode: true },
275	      });
276	      for (const entry of entriesToAccept) {
277	        await db.zipCode.upsert({
278	          where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
279	          create: { shop, zipCode: entry.zipCode, type: "allowed", isActive: true, label: `Requested by ${entry.name || entry.email}` },
280	          update: { type: "allowed", isActive: true },
281	        });
282	      }
283	      await db.waitlistEntry.updateMany({
284	        where: { id: { in: ids }, shop },
285	        data: { status: "accepted" },
286	      });
287	      return { success: true, action: "bulk-accepted", count: entriesToAccept.length };
288	    }
289	
290	    if (bulkType === "delete") {
291	      const result = await db.waitlistEntry.deleteMany({
292	        where: { id: { in: ids }, shop },
293	      });
294	      return { success: true, action: "bulk-deleted", count: result.count };
295	    }
296	
297	    return { error: "Unknown bulk action type." };
298	  }
299	
300	  if (intent === "delete-all-notified") {
301	    const deleted = await db.waitlistEntry.deleteMany({
302	      where: { shop, status: "notified" },
303	    });
304	    return { success: true, action: "deleted-notified", count: deleted.count };
305	  }
306	
307	  if (intent === "notify-all") {
308	    const notifyAllSub = await getShopSubscription(shop);
309	    if (PLAN_LIMITS[notifyAllSub.planTier].maxWaitlist < UNLIMITED) {
310	      return { error: "Notify All is only available on Pro or Ultimate plans. Please upgrade." };
311	    }
312	
313	    const allWaiting = await db.waitlistEntry.findMany({
314	      where: { shop, status: "waiting" },
315	      select: { id: true, email: true, zipCode: true },
316	    });
317	
318	    if (allWaiting.length === 0) {
319	      return { action: "notify-all", emails: [] as string[], count: 0, emailsSent: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
320	    }
321	
322	    await db.waitlistEntry.updateMany({
323	      where: { shop, status: "waiting" },
324	      data: { status: "notified" },
325	    });
326	
327	    const zipMap = new Map<string, number>();
328	    for (const entry of allWaiting) {
329	      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
330	    }
331	    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
332	    const emails = allWaiting.map((e) => e.email);
333	    const shopUrl = `https://${shop}`;
334	    const emailResults = await Promise.allSettled(
335	      allWaiting.map((e) =>
336	        sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl, emailOpts),
337	      ),
338	    );
339	    const emailsSent = emailResults.filter(
340	      (r) => r.status === "fulfilled" && r.value,
341	    ).length;
342	
343	    return { action: "notify-all", emails, count: emails.length, emailsSent, zipBreakdown };
344	  }
345	
346	  if (intent === "accept") {
347	    const id = String(formData.get("id"));
348	    const entry = await db.waitlistEntry.findUnique({ where: { id } });
349	    if (!entry || entry.shop !== shop) {
350	      return { error: "Entry not found." };
351	    }
352	
353	    await db.zipCode.upsert({
354	      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
355	      create: {
356	        shop,
357	        zipCode: entry.zipCode,
358	        type: "allowed",
359	        isActive: true,
360	        label: `Requested by ${entry.name || entry.email}`,
361	      },
362	      update: {
363	        type: "allowed",
364	        isActive: true,
365	      },
366	    });
367	
368	    await db.waitlistEntry.update({
369	      where: { id },
370	      data: { status: "accepted" },
371	    });
372	
373	    return { success: true, action: "accepted", zipCode: entry.zipCode };
374	  }
375	
376	  return null;
377	};
