379	const STATUS_OPTIONS = [
380	  { content: "Waiting", value: "waiting" },
381	  { content: "Accepted", value: "accepted" },
382	  { content: "Notified", value: "notified" },
383	  { content: "Converted", value: "converted" },
384	];
385	
386	const STATUS_TONE: Record<string, "attention" | "success" | "info" | undefined> = {
387	  waiting: "attention",
388	  accepted: "success",
389	  notified: "info",
390	  converted: "success",
391	};
