393	function StatusAction({ id, status, onChangeStatus }: { id: string; status: string; onChangeStatus: (id: string, val: string) => void }) {
394	  const [popoverActive, setPopoverActive] = useState(false);
395	
396	  const activator = (
397	    /* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
398	    <div onClick={(e) => e.stopPropagation()}>
399	      <Tooltip content="Change status">
400	        <Button
401	          size="slim"
402	          variant="tertiary"
403	          icon={EditIcon}
404	          onClick={() => setPopoverActive((v) => !v)}
405	          accessibilityLabel="Change status"
406	        />
407	      </Tooltip>
408	    </div>
409	  );
410	
411	  return (
412	    <Popover
413	      active={popoverActive}
414	      activator={activator}
415	      onClose={() => setPopoverActive(false)}
416	      preferredAlignment="left"
417	    >
418	      <ActionList
419	        items={STATUS_OPTIONS.filter((o) => o.value !== status).map((o) => ({
420	          content: o.content,
421	          onAction: () => {
422	            onChangeStatus(id, o.value);
423	            setPopoverActive(false);
424	          },
425	        }))}
426	      />
427	    </Popover>
428	  );
429	}
