441	export default function WaitlistPage() {
442	  const { entries, stats, subscription } = useLoaderData<typeof loader>();
443	  const fetcher = useFetcher<typeof action>();
444	  const shopify = useAppBridge();
445	  const navigate = useNavigate();
446	
447	  const limits = PLAN_LIMITS[subscription.planTier];
448	  const isFreePlan = limits.maxWaitlist === 0;
449	  const isStarterPlan = limits.maxWaitlist < UNLIMITED && limits.maxWaitlist > 0;
450	
451	  const [searchQuery, setSearchQuery] = useState("");
452	  const [statusFilter, setStatusFilter] = useState("all");
453	  const [currentPage, setCurrentPage] = useState(1);
454	  const [addModalOpen, setAddModalOpen] = useState(false);
455	  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
456	  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
457	  const [notifyResult, setNotifyResult] = useState<{
458	    zipCode: string;
459	    emails: string[];
460	    count: number;
461	    emailsSent?: number;
462	  } | null>(null);
463	  const [copySuccess, setCopySuccess] = useState(false);
464	
465	  // ZIP checkbox selection
466	  const [selectedZips, setSelectedZips] = useState<Set<string>>(new Set());
467	
468	  // IndexTable row selection
469	  const [selectedEntryIds, setSelectedEntryIds] = useState<string[]>([]);
470	  // Confirmation modals for destructive actions
471	  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
472	  const [confirmClearNotifiedOpen, setConfirmClearNotifiedOpen] = useState(false);
473	  const [confirmBulkDeleteOpen, setConfirmBulkDeleteOpen] = useState(false);
474	  const [confirmNotifyAllOpen, setConfirmNotifyAllOpen] = useState(false);
475	
476	  // Form state
477	  const [newEmail, setNewEmail] = useState("");
478	  const [newZipCode, setNewZipCode] = useState("");
479	  const [newNote, setNewNote] = useState("");
480	
481	  const actionError =
482	    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
483	
484	  const isDeleteLoading =
485	    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "delete";
486	  const isBulkDeleteLoading =
487	    fetcher.state !== "idle" &&
488	    fetcher.formData?.get("intent") === "bulk-action" &&
489	    fetcher.formData?.get("bulkType") === "delete";
490	  const isClearNotifiedLoading =
491	    fetcher.state !== "idle" &&
492	    fetcher.formData?.get("intent") === "delete-all-notified";
493	
494	  // Compute per-ZIP waiting counts for the "Notify Waitlist" section
495	  const zipWaitingCounts = useMemo(() => {
496	    const map = new Map<string, number>();
497	    for (const e of entries as WaitlistEntry[]) {
498	      if (e.status === "waiting") {
499	        map.set(e.zipCode, (map.get(e.zipCode) ?? 0) + 1);
500	      }
501	    }
502	    return Array.from(map.entries())
503	      .map(([zipCode, count]) => ({ zipCode, count }))
504	      .sort((a, b) => b.count - a.count);
505	  }, [entries]);
506	
507	  // Handle notify results (zip, selected-zips, bulk-action-notify)
508	  useEffect(() => {
509	    if (
510	      fetcher.data &&
511	      "action" in fetcher.data &&
512	      (fetcher.data.action === "notify-zip" || fetcher.data.action === "notify-selected-zips" || fetcher.data.action === "bulk-action-notify" || fetcher.data.action === "notify-all")
513	    ) {
514	      const data = fetcher.data as {
515	        action: string;
516	        zipCode?: string;
517	        emails: string[];
518	        count: number;
519	        emailsSent?: number;
520	        zipBreakdown?: { zipCode: string; count: number }[];
521	      };
522	      if (data.action === "notify-zip") {
523	        setNotifyResult({ zipCode: data.zipCode!, emails: data.emails, count: data.count, emailsSent: data.emailsSent });
524	      } else if (data.action === "notify-all") {
525	        setNotifyResult({
526	          zipCode: "All waiting ZIP codes",
527	          emails: data.emails,
528	          count: data.count,
529	          emailsSent: data.emailsSent,
530	        });
531	      } else {
532	        setNotifyResult({
533	          zipCode: data.zipBreakdown?.map(z => z.zipCode).join(", ") ?? "",
534	          emails: data.emails,
535	          count: data.count,
536	          emailsSent: data.emailsSent,
537	        });
538	      }
539	      setNotifyResultModalOpen(true);
540	      setSelectedZips(new Set());
541	
542	      // Fire a toast warning when customers were waiting but no emails were sent —
543	      // this ensures the merchant sees the problem even if they dismiss the result modal quickly.
544	      if (data.count > 0 && data.emailsSent === 0) {
545	        shopify.toast.show(
546	          "No emails were sent. Check your email settings in Settings \u2192 Email Notifications.",
547	          { isError: true },
548	        );
549	      }
550	    }
551	  }, [fetcher.data, shopify]);
552	
553	  const filteredEntries = useMemo(() => {
554	    let filtered = entries as WaitlistEntry[];
555	    if (searchQuery.trim()) {
556	      const q = searchQuery.trim().toLowerCase();
557	      filtered = filtered.filter(
558	        (e) =>
559	          e.email.toLowerCase().includes(q) ||
560	          e.zipCode.toLowerCase().includes(q) ||
561	          (e.note && e.note.toLowerCase().includes(q)),
562	      );
563	    }
564	    if (statusFilter !== "all") {
565	      filtered = filtered.filter((e) => e.status === statusFilter);
566	    }
567	    return filtered;
568	  }, [entries, searchQuery, statusFilter]);
569	
570	  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
571	  const paginatedEntries = useMemo(() => {
572	    const start = (currentPage - 1) * PAGE_SIZE;
573	    return filteredEntries.slice(start, start + PAGE_SIZE);
574	  }, [filteredEntries, currentPage]);
575	
576	  const handleSearchChange = useCallback((val: string) => {
577	    setSearchQuery(val);
578	    setCurrentPage(1);
579	  }, []);
580	
581	  const handleFilterChange = useCallback((val: string) => {
582	    setStatusFilter(val);
583	    setCurrentPage(1);
584	  }, []);
585	
586	  const handleAdd = useCallback(() => {
587	    if (!newEmail.trim() || !newZipCode.trim()) return;
