201	export const loader = async ({ request }: LoaderFunctionArgs) => {
202	  const { session } = await authenticate.admin(request);
203	  const shop = session.shop;
204	
205	  const [features, myVotes] = await Promise.all([
206	    db.featureRequest.findMany({
207	      orderBy: { votesCount: "desc" },
208	      take: 500,
209	    }),
210	    db.featureVote.findMany({
211	      where: { shop },
212	      select: { featureRequestId: true },
213	    }),
214	  ]);
215	
216	  const votedIds = myVotes.map((v) => v.featureRequestId);
217	
218	  const stats = {
219	    total: features.length,
220	    under_review: features.filter((f) => f.status === "under_review").length,
221	    planned: features.filter((f) => f.status === "planned").length,
222	    in_progress: features.filter((f) => f.status === "in_progress").length,
223	    done: features.filter(
224	      (f) => f.status === "done" || f.status === "shipped",
225	    ).length,
226	  };
227	
228	  const isAdmin = shop === ADMIN_SHOP;
229	
230	  return { features, votedIds, shop, stats, isAdmin };
231	};
