23	function calculateDeliveryDate(
24	  estimatedDays: string,
25	  daysOfWeek: string | null,
26	): string | null {
27	  const match = estimatedDays.match(/^(\d+)/);
28	  if (!match) return null;
29	  const minDays = parseInt(match[1], 10);
30	  if (isNaN(minDays) || minDays < 0) return null;
31	
32	  const deliveryDayNames = daysOfWeek
33	    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
34	    : ["mon", "tue", "wed", "thu", "fri"];
35	
36	  const dayMap: Record<string, number> = {
37	    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
38	  };
39	  const deliveryDayNumbers = new Set(
40	    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
41	  );
42	
43	  if (deliveryDayNumbers.size === 0) {
44	    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
45	  }
46	
47	  const date = new Date();
48	  let businessDaysAdded = 0;
49	
50	  while (businessDaysAdded < minDays) {
51	    date.setDate(date.getDate() + 1);
52	    if (deliveryDayNumbers.has(date.getDay())) {
53	      businessDaysAdded++;
54	    }
55	  }
56	
57	  while (!deliveryDayNumbers.has(date.getDay())) {
58	    date.setDate(date.getDate() + 1);
59	  }
